// Edit the clipPath below to the video you want to analyze.
// The path is relative to the shared volume root seen inside the containers (/data/shared).
// maxFrames caps how many frames get captioned (null = use the analyzer default).
return [{ json: { clipPath: '/data/shared/clips/your-clip.mp4', audio: false, maxFrames: null } }];

const a = $json;
let prompt = 'You are analyzing a short video. Below is an ordered sequence of frame captions (with timestamps in seconds) extracted by an AI vision model, plus an optional dialogue transcript.

Frame captions in order:
';
a.frames.forEach(f => { prompt += `[${f.t}s] ${f.caption}
`; });
if (a.transcript) prompt += `
Dialogue transcript:
${a.transcript}
`;
prompt += '
Based on this ordered sequence, write a concise 2-3 sentence summary of what is happening in the video, naming the main subject and setting.
';
return [{ json: { clip: a.clip, duration: a.duration, frames: a.frames, transcript: a.transcript, geminiPrompt: prompt } }];

const g = $json.candidates?.[0]?.content?.parts?.map(p => p.text).join(' ') ?? '';
const a = $('Build Gemini Prompt').first().json;
return [{ json: { clip: a.clip, duration: a.duration, summary: g.trim(), frames: a.frames, transcript: a.transcript } }];
